import{_ as a,o as l,c as r,a5 as t}from"./chunks/framework.Cooo9kuv.js";const b=JSON.parse('{"title":"Z-BlogPHP 广告投放插件 — 全能广告管理","description":"","frontmatter":{"标题":"ZBlogPHP 广告投放插件 — 全能广告管理","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["zblog主题插件"],"标签":["Z-BlogPHP","侧栏广告","信息流广告","分类定向","图片广告","对联广告","广告管理","弹窗广告","插屏广告","数据统计"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"20+ 广告展示位置","slug":"_20-广告展示位置","link":"#_20-广告展示位置","children":[]},{"level":3,"title":"图片与代码两种广告类型","slug":"图片与代码两种广告类型","link":"#图片与代码两种广告类型","children":[]},{"level":3,"title":"精细投放控制","slug":"精细投放控制","link":"#精细投放控制","children":[]},{"level":3,"title":"实时数据统计","slug":"实时数据统计","link":"#实时数据统计","children":[]},{"level":3,"title":"多语言支持","slug":"多语言支持","link":"#多语言支持","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：全局设置","slug":"第二步-全局设置","link":"#第二步-全局设置","children":[]},{"level":3,"title":"第三步：创建广告","slug":"第三步-创建广告","link":"#第三步-创建广告","children":[]},{"level":3,"title":"第四步：管理广告列表","slug":"第四步-管理广告列表","link":"#第四步-管理广告列表","children":[]},{"level":3,"title":"第五步：配置侧栏模块","slug":"第五步-配置侧栏模块","link":"#第五步-配置侧栏模块","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.4.2（2026-06-27）","slug":"v1-4-2-2026-06-27","link":"#v1-4-2-2026-06-27","children":[]},{"level":3,"title":"v1.1（2024）","slug":"v1-1-2024","link":"#v1-1-2024","children":[]}]}],"relativePath":"md/zblog主题插件/ZBlogPHP 广告投放插件 — 全能广告管理.md","filePath":"md/zblog主题插件/ZBlogPHP 广告投放插件 — 全能广告管理.md"}'),o={name:"md/zblog主题插件/ZBlogPHP 广告投放插件 — 全能广告管理.md"};function n(i,e,p,s,h,c){return l(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="z-blogphp-广告投放插件-—-全能广告管理" tabindex="-1">Z-BlogPHP 广告投放插件 — 全能广告管理 <a class="header-anchor" href="#z-blogphp-广告投放插件-—-全能广告管理" aria-label="Permalink to &quot;Z-BlogPHP 广告投放插件 — 全能广告管理&quot;">​</a></h1><blockquote><p>支持图片和安全 HTML 代码两种广告类型，覆盖文章页、列表页、搜索页、归档页、404 页面等 20+ 展示位置，内置弹窗、插屏、对联、右下角、滑入、侧栏跟随等多种交互形式，提供分类定向、时段排期、权重轮播、蜘蛛排除、移动端过滤等精细投放策略，并集成展示量与点击量实时统计。</p></blockquote><p><strong>版本</strong>：v1.4.2<br><strong>适配</strong>：Z-BlogPHP 1.7.0+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-14.png" alt=""></p><p>本插件为 Z-BlogPHP 提供一站式的广告投放管理能力，您可以在后台集中创建、编辑、启停所有广告单元，无需修改主题模板即可将广告注入到网站任意页面位置。</p><p>插件支持两种广告素材类型：图片广告（可本地上传至插件图库）和安全 HTML 代码广告（自动过滤 script 标签和事件属性，防止 XSS 风险）。每条广告均可设置展示位置、目标分类、起止时间、权重和排列对齐方式。</p><p>前台展示方面，插件覆盖了文章顶部、中部、底部、第 N 段落后、H 标签后、面包屑导航下、评论区、原生推荐卡片等文章内嵌位置，以及弹窗、全屏插屏、右下角悬浮、左右对联、顶部通栏、底部通栏、滚动触发滑入、侧栏模块、侧边跟随模块、列表信息流、搜索页、归档页、404 页面等页面级广告位。每种广告形式均配有独立的开关控制和关闭按钮，访客可主动关闭不感兴趣的广告。</p><p>插件还内置了展示量和点击量统计系统，基于 IntersectionObserver 自动追踪广告曝光，通过 sendBeacon 上报点击事件，后台可按天查看每条广告的数据表现。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="_20-广告展示位置" tabindex="-1">20+ 广告展示位置 <a class="header-anchor" href="#_20-广告展示位置" aria-label="Permalink to &quot;20+ 广告展示位置&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-15.png" alt=""></p><p>插件覆盖网站前台的几乎所有页面类型和内容区域，每个位置均可独立开关：</p><p>— 文章内嵌位置：文章顶部、文章中部、文章底部、第 N 段落后、H 标签后、面包屑导航下、原生推荐卡片、评论区（支持顶部/底部/间隔插入，可控制插入条数）</p><p>— 页面级广告：弹窗广告（页面加载后自动弹出，带遮罩层和关闭按钮）、全屏插屏广告（倒计时自动关闭，可跳过）、右下角悬浮广告（可设距边缘距离）、左右对联广告（小屏幕自动隐藏）、顶部通栏、底部通栏</p><p>— 滚动触发：滑入广告（页面滚动到指定百分比时从底部滑入，带关闭按钮）</p><p>— 侧栏集成：侧栏广告模块和侧边跟随模块，以 Z-BlogPHP 原生模块形式注册，可在模块管理中拖拽排序</p><p>— 列表与归档：列表信息流广告（自动在文章列表项之间均匀插入，可设插入条数）、归档页广告、搜索页广告、404 页面广告</p><h3 id="图片与代码两种广告类型" tabindex="-1">图片与代码两种广告类型 <a class="header-anchor" href="#图片与代码两种广告类型" aria-label="Permalink to &quot;图片与代码两种广告类型&quot;">​</a></h3><p>— 图片广告：支持本地上传（jpg / jpeg / png / gif / webp / bmp），上传后自动存入插件图库，可从图库中浏览和选择已有图片；支持设置图片宽度、高度和 object-fit 填充模式（contain / cover / fill / none / scale-down）；图片支持懒加载（loading=”lazy”）</p><p>— 安全 HTML 代码广告：可直接粘贴第三方广告代码，插件自动过滤 script 标签、on* 事件属性和 javascript: 协议链接，防止恶意代码执行</p><h3 id="精细投放控制" tabindex="-1">精细投放控制 <a class="header-anchor" href="#精细投放控制" aria-label="Permalink to &quot;精细投放控制&quot;">​</a></h3><p>— 分类定向：每条广告可指定展示在哪些分类的文章中，未选分类的文章不展示该广告</p><p>— 时段排期：支持设置广告的生效起始时间和结束时间，到期自动停投</p><p>— 多广告展示模式：同一位置有多条广告时，支持随机展示、按权重轮播、全部展示三种模式；权重轮播基于 Cookie 记录，确保同一访客每次看到不同广告</p><p>— 蜘蛛排除：可开启搜索引擎爬虫屏蔽，避免广告内容影响 SEO 收录</p><p>— 移动端过滤：可关闭移动端广告展示，针对手机用户提供清爽的浏览体验</p><p>— 排列对齐：每条广告可独立设置左对齐、居中、右对齐</p><p>— 链接控制：支持新窗口打开（target=”_blank”）和 nofollow 属性</p><h3 id="实时数据统计" tabindex="-1">实时数据统计 <a class="header-anchor" href="#实时数据统计" aria-label="Permalink to &quot;实时数据统计&quot;">​</a></h3><p>— 展示量追踪：基于 IntersectionObserver API，广告元素进入视口 50% 以上时自动记录一次展示</p><p>— 点击量追踪：通过事件委托捕获广告区域内链接点击，使用 sendBeacon 确保页面跳转前数据不丢失</p><p>— 后台统计面板：每条广告显示当日展示量和点击量，支持按天查看历史数据</p><h3 id="多语言支持" tabindex="-1">多语言支持 <a class="header-anchor" href="#多语言支持" aria-label="Permalink to &quot;多语言支持&quot;">​</a></h3><p>插件后台支持中文和英文界面切换，所有广告位置名称、按钮文案、模块标题均提供双语翻译。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 wz_ad 文件夹上传至网站 zb_users/plugin/ 目录，进入 Z-BlogPHP 后台「插件管理」页面，找到「WZ Ad Manager」并点击启用。启用后插件会自动创建广告数据表和统计表，并注册侧栏广告、侧边跟随两个模块。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-16.png" alt=""></p><h3 id="第二步-全局设置" tabindex="-1">第二步：全局设置 <a class="header-anchor" href="#第二步-全局设置" aria-label="Permalink to &quot;第二步：全局设置&quot;">​</a></h3><p>进入后台「广告管理」页面，在全局设置区域配置以下选项：</p><p>— 启用插件总开关<br> — 选择后台界面语言（中文 / English）<br> — 设置广告多展示模式（随机 / 权重轮播 / 全部展示）<br> — 配置图片默认宽度、高度和填充模式<br> — 开启或关闭蜘蛛屏蔽、移动端广告、新窗口打开、nofollow 等选项<br> — 设置广告标签（「广告」角标）是否显示</p><h3 id="第三步-创建广告" tabindex="-1">第三步：创建广告 <a class="header-anchor" href="#第三步-创建广告" aria-label="Permalink to &quot;第三步：创建广告&quot;">​</a></h3><p>点击「添加广告」按钮进入广告编辑表单：</p><p>— 选择广告类型（图片 / 代码），图片类型可上传本地图片或从图库选择<br> — 填写广告标题和链接地址<br> — 勾选展示位置（支持多选，可同时投放到多个位置）<br> — 选择目标分类（留空表示全部分类）<br> — 设置起止时间、权重和排列对齐方式<br> — 根据所选位置配置对应参数（如段落序号 N、H 标签级别、评论插入位置和条数、列表插入条数、插屏倒计时秒数、滑入触发百分比、右下角距边缘像素等）</p><p>保存后广告立即生效（状态为启用且时间在有效期内）。</p><h3 id="第四步-管理广告列表" tabindex="-1">第四步：管理广告列表 <a class="header-anchor" href="#第四步-管理广告列表" aria-label="Permalink to &quot;第四步：管理广告列表&quot;">​</a></h3><p>广告列表页展示所有已创建的广告，每条广告显示标题、类型、展示位置、状态、当日展示量/点击量。可对已有广告进行编辑、启用/停用、删除操作。</p><h3 id="第五步-配置侧栏模块" tabindex="-1">第五步：配置侧栏模块 <a class="header-anchor" href="#第五步-配置侧栏模块" aria-label="Permalink to &quot;第五步：配置侧栏模块&quot;">​</a></h3><p>进入「模块管理」页面，将「侧栏广告」和「侧边跟随广告」模块拖入对应侧栏位置即可在前台展示。如果未启用侧栏广告开关，模块内容为空，不会显示。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 安全 HTML 代码广告经过严格过滤，会移除所有 script 标签、on* 事件属性和 javascript: 协议链接，请勿在代码广告中依赖这些功能</p><p>— 图片广告上传至插件 images 目录，请确保该目录有写入权限（插件安装时会自动创建）</p><p>— 权重轮播模式依赖 Cookie 记录当前轮播位置，如访客清除 Cookie 则重新从权重最高的广告开始展示</p><p>— 蜘蛛排除功能通过 User-Agent 字符串匹配常见搜索引擎爬虫，包括 Googlebot、Bingbot、百度蜘蛛、搜狗蜘蛛、360 蜘蛛、字节蜘蛛等，可能无法覆盖所有爬虫</p><p>— 展示量统计基于 IntersectionObserver，在部分老旧浏览器中会降级为不统计（不影响广告展示）</p><p>— 评论区广告通过 JavaScript 动态插入到评论列表区域，依赖主题中 <code>#comments</code> 等常见评论容器选择器，如主题使用非标准结构可能无法自动插入，需联系作者适配</p><p>— 卸载插件时保留数据表和 config.json，如重新安装数据不丢失；如需彻底清除，请手动删除 zb_users/plugin/wz_ad/ 目录及数据库中 wz_ad_list、wz_ad_stats 两张表</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 作者网站：softbangong.top<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-4-2-2026-06-27" tabindex="-1">v1.4.2（2026-06-27） <a class="header-anchor" href="#v1-4-2-2026-06-27" aria-label="Permalink to &quot;v1.4.2（2026-06-27）&quot;">​</a></h3><p>— 新增 H 标签后广告位置，支持指定第 N 个 H 标签及标签级别（h1-h6）<br> — 新增滑入广告的触发百分比参数（per-ad 级别配置）<br> — 新增右下角广告距边缘像素参数（per-ad 级别配置）<br> — 新增评论广告的插入位置和插入条数配置<br> — 新增插屏广告的倒计时秒数参数（per-ad 级别配置）<br> — 新增面包屑导航下广告位置<br> — 新增原生推荐广告卡片样式<br> — 新增 404 页面、归档页、搜索页广告位置<br> — 广告图片新增 object-fit 填充模式配置（contain / cover / fill / none / scale-down）<br> — 新增图片懒加载（loading=”lazy”）优化页面性能<br> — 新增插件内置图库管理，支持图片上传、浏览和复用</p><h3 id="v1-1-2024" tabindex="-1">v1.1（2024） <a class="header-anchor" href="#v1-1-2024" aria-label="Permalink to &quot;v1.1（2024）&quot;">​</a></h3><p>— 初版发布，支持文章顶部/中部/底部、段落后、弹窗、右下角、侧栏、对联、顶部通栏、底部通栏、侧边跟随、列表信息流等广告位置<br> — 支持图片和代码两种广告类型<br> — 支持分类定向、时段排期、权重轮播<br> — 支持蜘蛛排除和移动端过滤<br> — 集成展示量和点击量统计</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2995.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2995.html</a></p>',67)])])}const g=a(o,[["render",n]]);export{b as __pageData,g as default};
